const upsertMilestoneOverride = `-- name: UpsertMilestoneOverride :one
INSERT INTO world_milestone_overrides (milestone_id, threshold_points_per_active, target_day, force_reach, paused,
                                       updated_by, updated_at)
VALUES ($1, $2, $3, $4, $5,
        $6, $7)
ON CONFLICT (milestone_id) DO UPDATE
SET threshold_points_per_active = EXCLUDED.threshold_points_per_active,
    target_day                  = EXCLUDED.target_day,
    force_reach                 = EXCLUDED.force_reach,
    paused                      = EXCLUDED.paused,
    updated_by                  = EXCLUDED.updated_by,
    updated_at                  = EXCLUDED.updated_at
RETURNING milestone_id, threshold_points_per_active, target_day, force_reach, paused, updated_by, updated_at
`

type UpsertMilestoneOverrideParams struct {
	MilestoneID              string      `json:"milestone_id"`
	ThresholdPointsPerActive pgtype.Int8 `json:"threshold_points_per_active"`
	TargetDay                pgtype.Int4 `json:"target_day"`
	ForceReach               bool        `json:"force_reach"`
	Paused                   bool        `json:"paused"`
	UpdatedBy                uuid.UUID   `json:"updated_by"`
	UpdatedAt                time.Time   `json:"updated_at"`
}

func (q *Queries) UpsertMilestoneOverride(ctx context.Context, arg UpsertMilestoneOverrideParams) (WorldMilestoneOverride, error) {
	row := q.db.QueryRow(ctx, upsertMilestoneOverride,
		arg.MilestoneID,
		arg.ThresholdPointsPerActive,
		arg.TargetDay,
		arg.ForceReach,
		arg.Paused,
		arg.UpdatedBy,
		arg.UpdatedAt,
	)
	var i WorldMilestoneOverride
	err := row.Scan(
		&i.MilestoneID,
		&i.ThresholdPointsPerActive,
		&i.TargetDay,
		&i.ForceReach,
		&i.Paused,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertWorldDailyTotal = `-- name: UpsertWorldDailyTotal :exec
INSERT INTO world_daily_totals (game_day, credited_milli, catch_up_bonus_milli, countable_milli, dau,
                                per_capita_milli, computed_at)
SELECT $1::date,
       COALESCE(SUM(points_milli), 0)::bigint,
       COALESCE(SUM(catch_up_bonus_milli), 0)::bigint,
       COALESCE(SUM(LEAST($2::bigint, points_milli - catch_up_bonus_milli)), 0)::bigint,
       COUNT(*)::int,
       (COALESCE(SUM(LEAST($2::bigint, points_milli - catch_up_bonus_milli)), 0) / GREATEST(COUNT(*), 1))::bigint,
       $3::timestamptz
FROM daily_contribution
WHERE game_day = $1::date AND points_milli > 0
ON CONFLICT (game_day) DO UPDATE
SET credited_milli       = EXCLUDED.credited_milli,
    catch_up_bonus_milli = EXCLUDED.catch_up_bonus_milli,
    countable_milli      = EXCLUDED.countable_milli,
    dau                  = EXCLUDED.dau,
    per_capita_milli     = EXCLUDED.per_capita_milli,
    computed_at          = EXCLUDED.computed_at
WHERE world_daily_totals.closed_at IS NULL
`

type UpsertWorldDailyTotalParams struct {
	GameDay    pgtype.Date `json:"game_day"`
	CapMilli   int64       `json:"cap_milli"`
	ComputedAt time.Time   `json:"computed_at"`
}

// Recompute (never increment) an OPEN game day from daily_contribution; closed days never change (W5).
func (q *Queries) UpsertWorldDailyTotal(ctx context.Context, arg UpsertWorldDailyTotalParams) error {
	_, err := q.db.Exec(ctx, upsertWorldDailyTotal, arg.GameDay, arg.CapMilli, arg.ComputedAt)
	return err
}
